1	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
2	import { supabase } from "@/integrations/supabase/client";
3	import { useAuth } from "@/hooks/useAuth";
4	import { toast } from "sonner";
5	
6	// ─── Types ────────────────────────────────────────────────────────────────────
7	
8	export type HireOutcome =
9	  | "great_hire"
10	  | "good_hire"
11	  | "average_hire"
12	  | "bad_hire"
13	  | "rejected_interview"
14	  | "rejected_screening"
15	  | "no_show"
16	  | "withdrew";
17	
18	export interface HireOutcomeRecord {
19	  id: string;
20	  user_id: string;
21	  resume_id: string;
22	  job_id: string;
23	  outcome: HireOutcome;
24	  notes: string | null;
25	  rank_at_outcome: number | null;
26	  created_at: string;
27	}
28	
29	export interface HitRateStats {
30	  total_marked: number;
31	  great_hires: number;
32	  good_hires: number;
33	  bad_hires: number;
34	  hit_rate_percent: number;
35	  avg_score_of_great: number;
36	  avg_score_of_bad: number;
37	}
38	
39	interface UpsertOutcomeParams {
40	  resumeId: string;
41	  jobId: string;
42	  outcome: HireOutcome;
43	  notes?: string;
44	  currentScore?: number;
45	}
46	
47	// ─── Hook: useHireOutcome ────────────────────────────────────────────────────
48	
49	/**
50	 * Gets the current outcome for a specific resume+job combination.
51	 */
52	export function useHireOutcome(resumeId: string | undefined, jobId: string | undefined) {
53	  return useQuery<HireOutcomeRecord | null>({
54	    queryKey: ["hire-outcome", resumeId, jobId],
55	    queryFn: async (): Promise<HireOutcomeRecord | null> => {
56	      if (!resumeId || !jobId) return null;
57	
58	      const { data, error } = await (supabase as any)
59	        .from("hire_outcomes")
60	        .select("*")
61	        .eq("resume_id", resumeId)
62	        .eq("job_id", jobId)
63	        .maybeSingle();
64	
65	      if (error) throw error;
66	      return data as HireOutcomeRecord | null;
67	    },
68	    enabled: !!resumeId && !!jobId,
69	    staleTime: 2 * 60 * 1000, // 2 minutes
70	  });
71	}
72	
73	// ─── Hook: useSetHireOutcome ─────────────────────────────────────────────────
74	
75	/**
76	 * Upserts a hire outcome for a resume+job combination.
77	 */
78	export function useSetHireOutcome() {
79	  const queryClient = useQueryClient();
80	  const { user } = useAuth();
81	
82	  return useMutation<HireOutcomeRecord, Error, UpsertOutcomeParams>({
83	    mutationFn: async ({ resumeId, jobId, outcome, notes, currentScore }: UpsertOutcomeParams): Promise<HireOutcomeRecord> => {
84	      if (!user?.id) throw new Error("Not authenticated");
85	
86	      const payload = {
87	        user_id: user.id,
88	        resume_id: resumeId,
89	        job_id: jobId,
90	        outcome,
91	        notes: notes ?? null,
92	        rank_at_outcome: currentScore != null ? Math.round(currentScore) : null,
93	      };
94	
95	      const { data, error } = await (supabase as any)
96	        .from("hire_outcomes")
97	        .upsert(payload, { onConflict: "resume_id,job_id" })
98	        .select()
99	        .single();
100	
101	      if (error) throw error;
102	      return data as HireOutcomeRecord;
103	    },
104	
105	    onSuccess: (data) => {
106	      toast.success("Outcome saved");
107	      queryClient.invalidateQueries({ queryKey: ["hire-outcome", data.resume_id, data.job_id] });
108	      queryClient.invalidateQueries({ queryKey: ["hit-rate"] });
109	    },
110	
111	    onError: (error) => {
112	      toast.error(`Failed to save outcome: ${error.message}`);
113	    },
114	  });
115	}
116	
117	// ─── Hook: useDeleteHireOutcome ──────────────────────────────────────────────
118	
119	/**
120	 * Removes a hire outcome record.
121	 */
122	export function useDeleteHireOutcome() {
123	  const queryClient = useQueryClient();
124	
125	  return useMutation<void, Error, { resumeId: string; jobId: string }>({
126	    mutationFn: async ({ resumeId, jobId }) => {
127	      const { error } = await (supabase as any)
128	        .from("hire_outcomes")
129	        .delete()
130	        .eq("resume_id", resumeId)
131	        .eq("job_id", jobId);
132	
133	      if (error) throw error;
134	    },
135	
136	    onSuccess: (_data, { resumeId, jobId }) => {
137	      toast.success("Outcome removed");
138	      queryClient.invalidateQueries({ queryKey: ["hire-outcome", resumeId, jobId] });
139	      queryClient.invalidateQueries({ queryKey: ["hit-rate"] });
140	    },
141	
142	    onError: (error) => {
143	      toast.error(`Failed to remove outcome: ${error.message}`);
144	    },
145	  });
146	}
147	
148	// ─── Hook: useHitRate ───────────────────────────────────────────────────────
149	
150	/**
151	 * Fetches the user's aggregate hit rate statistics.
152	 */
153	export function useHitRate() {
154	  const { user } = useAuth();
155	
156	  return useQuery<HitRateStats | null>({
157	    queryKey: ["hit-rate", user?.id],
158	    queryFn: async (): Promise<HitRateStats | null> => {
159	      if (!user?.id) return null;
160	
161	      const { data, error } = await (supabase as any).rpc("user_hit_rate", {
162	        p_user_id: user.id,
163	      });
164	
165	      if (error) throw error;
166	
167	      // RPC returns an array with one row
168	      const row = Array.isArray(data) ? data[0] : data;
169	      if (!row) return null;
170	      return row as HitRateStats;
171	    },
172	    enabled: !!user?.id,
173	    staleTime: 5 * 60 * 1000, // 5 minutes
174	  });
175	}
