1	import { useMutation, useQueryClient } from "@tanstack/react-query";
2	import { supabase } from "@/integrations/supabase/client";
3	
4	interface SendSmsInput {
5	  resume_id: string;
6	  job_id: string;
7	  to_phone: string;
8	  message: string;
9	}
10	
11	interface SendSmsResult {
12	  success: boolean;
13	  twilio_sid?: string;
14	  error?: string;
15	  not_configured?: boolean;
16	}
17	
18	export function useSendSms() {
19	  const queryClient = useQueryClient();
20	
21	  return useMutation<SendSmsResult, Error, SendSmsInput>({
22	    mutationFn: async (input) => {
23	      const { data, error } = await supabase.functions.invoke<SendSmsResult>("send-sms", {
24	        body: input,
25	      });
26	      if (error) throw new Error(error.message);
27	      if (!data) throw new Error("No response from send-sms function");
28	      if (data.error) throw new Error(data.error);
29	      return data;
30	    },
31	    onSuccess: (_data, variables) => {
32	      // Invalidate sms_logs so any usage history views refresh
33	      queryClient.invalidateQueries({ queryKey: ["sms_logs"] });
34	      queryClient.invalidateQueries({ queryKey: ["sms_logs", variables.job_id] });
35	    },
36	  });
37	}
