62	
63	const DROPDOWN_OUTCOMES: Array<{ value: HireOutcome; label: string }> = [
64	  { value: "rejected_interview", label: "Rejected at interview" },
65	  { value: "rejected_screening", label: "Rejected at screening" },
66	  { value: "no_show", label: "No show" },
67	  { value: "withdrew", label: "Withdrew" },
