69	
70	const ALL_OUTCOMES = [...PRIMARY_OUTCOMES.map((o) => ({ value: o.value, label: o.label })), ...DROPDOWN_OUTCOMES];
71	
72	function getOutcomeDisplay(outcome: HireOutcome) {
73	  const primary = PRIMARY_OUTCOMES.find((o) => o.value === outcome);
74	  if (primary) return primary;
75	  const dropdown = DROPDOWN_OUTCOMES.find((o) => o.value === outcome);
76	  return dropdown
77	    ? {
78	        value: dropdown.value,
79	        label: dropdown.label,
80	        icon: <Minus className="h-4 w-4" />,
81	        colorClass: "border-border bg-muted/50 text-muted-foreground",
82	        badgeClass: "border-border bg-muted/50 text-muted-foreground",
83	      }
84	    : null;
