87	// ─── Component ───────────────────────────────────────────────────────────────
88	
89	export default function HireOutcomeCard({ resumeId, jobId, currentScore }: HireOutcomeCardProps) {
90	  const { data: existingOutcome, isLoading } = useHireOutcome(resumeId, jobId);
91	  const { mutate: setOutcome, isPending: isSaving } = useSetHireOutcome();
92	  const { mutate: deleteOutcome, isPending: isDeleting } = useDeleteHireOutcome();
93	
94	  const [selected, setSelected] = useState<HireOutcome | null>(null);
95	  const [notes, setNotes] = useState("");
96	  const [isEditing, setIsEditing] = useState(false);
97	
98	  // Determine current state
99	  const currentOutcome = existingOutcome?.outcome ?? null;
100	  const currentNotes = existingOutcome?.notes ?? "";
101	  const display = getOutcomeDisplay(currentOutcome ?? (selected as HireOutcome));
102	
103	  // When editing, use local state; when not, show saved state
104	  const showForm = isEditing || (!currentOutcome && selected !== null);
105	
106	  function handleSelectOutcome(outcome: HireOutcome) {
107	    setSelected(outcome);
108	    if (!isEditing && currentOutcome) {
109	      setIsEditing(true);
110	      setNotes(currentNotes);
111	    }
112	  }
113	
114	  function handleStartEdit() {
115	    setSelected(currentOutcome);
116	    setNotes(currentNotes);
117	    setIsEditing(true);
118	  }
119	
120	  function handleCancel() {
121	    setSelected(null);
122	    setNotes("");
123	    setIsEditing(false);
124	  }
125	
126	  function handleSave() {
127	    const outcomeToSave = isEditing ? (selected ?? currentOutcome) : selected;
128	    if (!outcomeToSave) return;
129	
130	    setOutcome(
131	      { resumeId, jobId, outcome: outcomeToSave, notes: notes.trim() || undefined, currentScore },
132	      {
133	        onSuccess: () => {
134	          setSelected(null);
135	          setNotes("");
136	          setIsEditing(false);
137	        },
138	      },
139	    );
140	  }
141	
142	  function handleDelete() {
143	    deleteOutcome(
144	      { resumeId, jobId },
145	      {
146	        onSuccess: () => {
147	          setSelected(null);
148	          setNotes("");
149	          setIsEditing(false);
150	        },
151	      },
152	    );
153	  }
154	
155	  if (isLoading) {
156	    return (
