62	// SMS best practice: 160 chars = 1 SMS credit. Over 160 splits into multiple.
63	const SMS_SOFT_LIMIT = 160;
64	const SMS_HARD_LIMIT = 1600;
65	
66	// ─── Character Counter ────────────────────────────────────────────────────────
67	
68	function CharCounter({ count }: { count: number }) {
69	  const segments = count === 0 ? 0 : Math.ceil(count / SMS_SOFT_LIMIT);
70	  const isOver = count > SMS_HARD_LIMIT;
71	  const isWarning = count > SMS_SOFT_LIMIT && !isOver;
72	
73	  return (
74	    <div className="flex items-center justify-between">
75	      <p className="text-[11px] text-muted-foreground">
76	        {count > SMS_SOFT_LIMIT && (
77	          <span className={isOver ? "text-destructive" : "text-amber-600"}>
78	            {segments} SMS segment{segments !== 1 ? "s" : ""}
79	            {" "}
80	          </span>
81	        )}
82	        Keep under 160 characters for a single SMS segment.
83	      </p>
84	      <span
85	        className={`text-[11px] tabular-nums font-mono ${
86	          isOver
87	            ? "text-destructive"
88	            : isWarning
89	            ? "text-amber-600"
90	            : "text-muted-foreground"
91	        }`}
92	      >
93	        {count}/{SMS_SOFT_LIMIT}
94	      </span>
95	    </div>
96	  );
97	}
