import { useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface SendSmsInput {
  resume_id?: string | null;
  job_id?: string | null;
  to_phone: string;
  message: string;
}

interface SendSmsResult {
  success: boolean;
  twilio_sid?: string;
  error?: string;
  not_configured?: boolean;
}

// Extended error type that carries the structured not_configured flag
export class SmsNotConfiguredError extends Error {
  not_configured = true as const;
  constructor(message: string) {
    super(message);
    this.name = "SmsNotConfiguredError";
  }
}

export function useSendSms() {
  const queryClient = useQueryClient();

  return useMutation<SendSmsResult, Error, SendSmsInput>({
    mutationFn: async (input) => {
      try {
        const { data, error } = await supabase.functions.invoke<SendSmsResult>("send-sms", {
          body: input,
        });

        if (error) {
          // Try to parse structured error body from the FunctionInvokeError context
          const body = await (error as any).context?.json?.().catch(() => null);
          if (body?.not_configured) {
            throw new SmsNotConfiguredError(body.error || "SMS not configured");
          }
          throw new Error(error.message);
        }

        if (!data) throw new Error("No response from send-sms function");
        if (data.not_configured) throw new SmsNotConfiguredError(data.error || "SMS not configured");
        if (data.error) throw new Error(data.error);
        return data;
      } catch (e) {
        throw e;
      }
    },
    onSuccess: (_data, variables) => {
      // Invalidate sms_logs so any usage history views refresh
      queryClient.invalidateQueries({ queryKey: ["sms_logs"] });
      if (variables.job_id) {
        queryClient.invalidateQueries({ queryKey: ["sms_logs", variables.job_id] });
      }
    },
  });
}

