// SMS best practice: 160 chars (GSM-7) or 70 chars (Unicode) per segment.
const SMS_HARD_LIMIT = 1600;

// M3: Unicode-aware segment counter
function countSegments(msg: string): { length: number; segments: number; limit: number } {
  const hasUnicode = /[^\x00-\x7F]/.test(msg);
  const limit = hasUnicode ? 70 : 160;
  const length = msg.length;
  const segments = length === 0 ? 0 : Math.ceil(length / limit);
  return { length, segments, limit };
}

// ─── Character Counter ────────────────────────────────────────────────────────

function CharCounter({ message }: { message: string }) {
  const { length, segments, limit } = countSegments(message);
  const isOver = length > SMS_HARD_LIMIT;
  const isWarning = length > limit && !isOver;

  return (
    <div className="flex items-center justify-between">
      <p className="text-xs text-muted-foreground">
        {length > limit && (
          <span className={isOver ? "text-destructive" : "text-amber-600"}>
            {segments} SMS segment{segments !== 1 ? "s" : ""}
            {" "}
          </span>
        )}
        Keep under {limit} characters for a single SMS segment.
      </p>
      <span
        className={`text-xs tabular-nums font-mono ${
          isOver
            ? "text-destructive"
            : isWarning
            ? "text-amber-600"
            : "text-muted-foreground"
        }`}
      >
        {length}/{limit}
      </span>
    </div>
  );
}

